'use strict';

// Pearl template tests. The fixture is a real mainnet getblocktemplate reply
// (25 transactions), so these assertions exercise the same bytes the daemon
// would have to accept.

const test = require('node:test');
const assert = require('node:assert');
const fs = require('node:fs');
const path = require('node:path');

const pearl = require('../pearl.js');
const { taprootAddressToScript } = require('../bitcoin_utils.js');

const FIXTURE = JSON.parse(
  fs.readFileSync(path.join(__dirname, 'fixtures', 'pearl-gbt-mainnet.json'), 'utf8')
);

// A real P2TR address generated by oyster on mainnet.
const POOL_ADDRESS = 'prl1p640xfps6m9uj6f8k7r7hlsaqph0ent8yta9ve9hh7enk7snrnp9s2lv4d0';

const HEADER_LEN = 108;
const INCOMPLETE_HEADER_LEN = 76;

function build() {
  return pearl.PearlBlockTemplate(FIXTURE, POOL_ADDRESS);
}

function reverseHex(hex) {
  return Buffer.from(hex, 'hex').reverse().toString('hex');
}

test('taproot address decodes to an OP_1 <32-byte> script', () => {
  const script = taprootAddressToScript(POOL_ADDRESS, 'prl');
  assert.strictEqual(script.length, 34);
  assert.strictEqual(script[0], 0x51); // OP_1 -> witness version 1
  assert.strictEqual(script[1], 0x20); // push 32 bytes
});

test('taproot decoding rejects the wrong network prefix', () => {
  // A correctly formed address from another chain must not be silently paid to.
  assert.throws(() => taprootAddressToScript(POOL_ADDRESS, 'bc'), /prefix/);
});

test('taproot decoding rejects non-bech32m input', () => {
  assert.throws(() => taprootAddressToScript('not-an-address', 'prl'), /Invalid taproot address/);
  assert.throws(() => taprootAddressToScript(12345, 'prl'), /Invalid taproot address/);
});

test('header is 108 bytes and carries no nonce field', () => {
  const tpl = build();
  const blob = Buffer.from(tpl.blocktemplate_blob, 'hex');
  assert.ok(blob.length > HEADER_LEN);

  // version (int32 LE)
  assert.strictEqual(blob.readInt32LE(0), FIXTURE.version);
  // prevBlock, stored byte-reversed relative to the RPC display order
  assert.strictEqual(blob.slice(4, 36).toString('hex'), reverseHex(FIXTURE.previousblockhash));
  // merkleRoot is a placeholder until convertPearlBlob fills it in
  assert.strictEqual(blob.slice(36, 68).toString('hex'), '00'.repeat(32));
  // time
  assert.strictEqual(blob.readUInt32LE(68), FIXTURE.curtime);
  // bits, little-endian on the wire
  assert.strictEqual(blob.readUInt32LE(72), Buffer.from(FIXTURE.bits, 'hex').readUInt32BE(0));
  // proofCommitment placeholder occupies where Bitcoin keeps its nonce
  assert.strictEqual(blob.slice(INCOMPLETE_HEADER_LEN, HEADER_LEN).toString('hex'), '00'.repeat(32));
});

test('reserved_offset points at the extranonce placeholder', () => {
  const tpl = build();
  const blob = Buffer.from(tpl.blocktemplate_blob, 'hex');
  const placeholder = blob.slice(tpl.reserved_offset, tpl.reserved_offset + 17);
  assert.strictEqual(placeholder.toString('hex'), 'cc'.repeat(17));
  assert.ok(tpl.reserved_offset > HEADER_LEN);
});

test('template reports the daemon height and a positive difficulty', () => {
  const tpl = build();
  assert.strictEqual(tpl.height, FIXTURE.height);
  assert.ok(Number.isFinite(tpl.difficulty) && tpl.difficulty > 0);
  assert.strictEqual(tpl.prev_hash, reverseHex(FIXTURE.previousblockhash));
});

test('difficulty uses Pearl\'s PowLimit base, not the 2^256 cryptonote base', () => {
  // Pearl is a btcd fork: difficulty is PowLimit/target with
  // PowLimitBits = 0x1b00ffff (0xffff << 192). Using the 2^256 base instead
  // inflates every difficulty by ~2^48, which silently wrecks hashrate
  // estimates and the coinHashFactorPRL calibration rather than failing loudly.
  const tpl = build();
  const target = BigInt(`0x${FIXTURE.target}`);
  const powLimit = BigInt(0xffff) << 192n;
  const expected = Number((powLimit * 1000n) / target) / 1000;
  assert.ok(Math.abs(tpl.difficulty - expected) / expected < 1e-6,
    `difficulty ${tpl.difficulty} is not PowLimit/target (${expected})`);
  // Guard the magnitude too: the 2^256 base would land around 5.4e21 here.
  assert.ok(tpl.difficulty > 1e6 && tpl.difficulty < 1e9);
});

test('every daemon transaction is carried through verbatim', () => {
  const tpl = build();
  const blobHex = tpl.blocktemplate_blob;
  assert.ok(FIXTURE.transactions.length > 0, 'fixture should exercise a non-empty mempool');
  for (const tx of FIXTURE.transactions) {
    assert.ok(blobHex.includes(tx.data.toLowerCase()), `missing tx ${tx.txid || tx.hash}`);
  }
  // Dropping or reordering transactions produces a wrong merkle root, so the
  // count encoded in the blob must be exactly daemon txs + coinbase.
  const txCountByte = Buffer.from(blobHex, 'hex')[HEADER_LEN];
  assert.strictEqual(txCountByte, FIXTURE.transactions.length + 1);
});

test('coinbase pays the pool via P2TR and commits to the witness root', () => {
  const tpl = build();
  const blob = Buffer.from(tpl.blocktemplate_blob, 'hex');

  const payScript = taprootAddressToScript(POOL_ADDRESS, 'prl');
  const payIndex = blob.indexOf(payScript);
  assert.ok(payIndex > 0, 'P2TR output script should appear in the coinbase');

  // The 8 bytes before the script's length byte are the output value.
  const value = blob.readBigUInt64LE(payIndex - 1 - 8);
  assert.strictEqual(value, BigInt(FIXTURE.coinbasevalue));

  const commitScript = pearl.witnessCommitmentScript(FIXTURE.default_witness_commitment);
  assert.ok(blob.includes(commitScript), 'witness commitment output should appear in the coinbase');
});

test('witness commitment script adds the magic prefix the daemon omits', () => {
  // Pearl's getblocktemplate returns the bare 32-byte commitment, unlike
  // Bitcoin Core which returns the whole scriptPubKey.
  const script = pearl.witnessCommitmentScript(FIXTURE.default_witness_commitment);
  assert.strictEqual(script.length, 38);
  assert.strictEqual(script.slice(0, 6).toString('hex'), '6a24aa21a9ed');
  assert.strictEqual(script.slice(6).toString('hex'), FIXTURE.default_witness_commitment);
  assert.throws(() => pearl.witnessCommitmentScript('00'), /default_witness_commitment/);
});

test('BIP34 height is pushed into the coinbase scriptSig', () => {
  const tpl = build();
  const blob = Buffer.from(tpl.blocktemplate_blob, 'hex');
  const heightPush = pearl.serializeNumber(FIXTURE.height);
  // scriptSig starts right after the coinbase input's 4-byte sequence-relative
  // header; searching is enough to prove the push is present and well formed.
  assert.ok(blob.includes(heightPush), 'coinbase must carry the BIP34 height push');
});

test('malformed templates fail closed rather than yielding a doomed block', () => {
  assert.throws(() => pearl.PearlBlockTemplate(null, POOL_ADDRESS), /Invalid PRL template/);

  const badPrev = Object.assign({}, FIXTURE, { previousblockhash: 'dead' });
  assert.throws(() => pearl.PearlBlockTemplate(badPrev, POOL_ADDRESS), /previousblockhash/);

  const badBits = Object.assign({}, FIXTURE, { bits: 'ff' });
  assert.throws(() => pearl.PearlBlockTemplate(badBits, POOL_ADDRESS), /bits/);

  const badTx = Object.assign({}, FIXTURE, { transactions: [{ data: 'zz', txid: 'x' }] });
  assert.throws(() => pearl.PearlBlockTemplate(badTx, POOL_ADDRESS), /Unparseable PRL transaction/);

  const badValue = Object.assign({}, FIXTURE, { coinbasevalue: -1 });
  assert.throws(() => pearl.PearlBlockTemplate(badValue, POOL_ADDRESS), /coinbasevalue/);
});

// --- certificate serialization (the submit side) ----------------------------
//
// These bytes are what makes a found block a block. The node deserializes the
// certificate before it will look at the header, so a field of the wrong width
// costs the whole reward with no error the pool would ever see.

function makeCert(version, publicDataLen, proofLen) {
  return pearl.serializePearlCertificate(
    version,
    Buffer.alloc(32, 0xab),
    Buffer.alloc(publicDataLen, 0xcd),
    Buffer.alloc(proofLen, 0xef)
  );
}

test('V1 certificates omit the public-data length prefix', () => {
  const cert = makeCert(1, pearl.PUBLIC_DATA_SIZE_V1, 100);
  assert.strictEqual(cert.length, 4 + 32 + pearl.PUBLIC_DATA_SIZE_V1 + 4 + 100);
  assert.strictEqual(cert.readUInt32LE(0), 1);
  assert.strictEqual(cert.readUInt32LE(4 + 32 + pearl.PUBLIC_DATA_SIZE_V1), 100);
});

test('V2 and V3 share a wire layout that length-prefixes the public data', () => {
  for (const version of [2, 3]) {
    const cert = makeCert(version, 200, 100);
    assert.strictEqual(cert.length, 4 + 32 + 4 + 200 + 4 + 100);
    assert.strictEqual(cert.readUInt32LE(0), version);
    assert.strictEqual(cert.readUInt32LE(36), 200);
    assert.strictEqual(cert.readUInt32LE(40 + 200), 100);
  }
});

test('certificate length is recoverable from a serialized block', () => {
  // The header follows the certificate, so finding it means walking exactly the
  // fields the node itself walks.
  for (const [version, publicDataLen] of [[1, pearl.PUBLIC_DATA_SIZE_V1], [2, 300], [3, 164]]) {
    const cert = makeCert(version, publicDataLen, 1000);
    const block = Buffer.concat([cert, Buffer.alloc(HEADER_LEN + 50)]);
    assert.strictEqual(pearl.pearlCertificateLength(block), cert.length);
  }
});

test('certificates that the node would reject are refused here instead', () => {
  assert.throws(() => makeCert(4, 164, 100), /certificate version/);
  // V1's public data is a fixed 164 bytes; anything else is a different shape.
  assert.throws(() => makeCert(1, 163, 100), /need 164/);
  assert.throws(() => makeCert(2, pearl.PUBLIC_DATA_MAX_SIZE_V2 + 1, 100), /max 4807/);
  assert.throws(() => makeCert(2, 200, 0), /proof size/);
  assert.throws(() => makeCert(2, 200, pearl.MAX_ZK_PROOF_SIZE + 1), /proof size/);
  assert.throws(
    () => pearl.serializePearlCertificate(2, Buffer.alloc(31), Buffer.alloc(200), Buffer.alloc(100)),
    /block hash/
  );
});

test('truncated blocks do not read past their own buffer', () => {
  assert.throws(() => pearl.pearlCertificateLength(Buffer.alloc(8)), /Truncated PRL block/);
  // A certificate whose proof length runs off the end of the block.
  const cert = makeCert(3, 164, 1000);
  assert.throws(() => pearl.pearlCertificateLength(cert.slice(0, cert.length - 1)), /Truncated PRL block/);
});
